55	        /// <param name="model"></param>
56	        /// <returns></returns>
57	        [HttpPost]
58	        public ActionResult FetchOrgList(LoginReqModel model)
59	        {
60	            var accessTokenCookie = CookieProvider.Instance.GetWeChatAuthCompleteAccessTokenFormCookie();
61	            var CookieJson = string.IsNullOrEmpty(accessTokenCookie) ? null : JsonConvert.DeserializeObject<CookieWeChatLoginStatus>(accessTokenCookie);
62	            //验证如果不是首次微信登录，则可以跳过验证码
63	            bool isCanJumpVerify = false;
64	            //不为空 则使用了微信快捷登录  如果不是首次微信登陆，则可以跳过验证码
65	            if (CookieJson != null && CookieJson.LoginStatus && !CookieJson.IsFirst && !string.IsNullOrEmpty(model.Phone) && !string.IsNullOrEmpty(CookieJson.UserPhone))
66	            {
67	                //如果没有修改过手机号，可以跳过验证码验证
68	                if (model.Phone.Equals(CookieJson.UserPhone)) isCanJumpVerify = true;
69	            }
70	            //如果不能跳过或者验证不成功
71	            var chkRet = isCanJumpVerify ? ErrCodeEnum.Success : CaptchaService.Instance.Verify(model.Code, model.Phone, false);
72	
73	            if (chkRet != ErrCodeEnum.Success)
74	            {
75	                return JsonResult(BaseResult.CrtEx(chkRet));
76	            }
77	
78	            var datas = OrgService.Instance.GetValidOrgInfoList(model.Phone);
79	
80	            return JsonResult(DataResult<IList<BasicOrgInfo>>.Success(datas));
81	        }
