149	                //如果没有修改过手机号，可以跳过验证码验证
150	                if (model.Phone.Equals(CookieJson.UserPhone)) isCanJumpVerify = true;
151	            }
152	            if (!isCanJumpVerify && string.IsNullOrEmpty(model.Code))
153	            {
154	                return JsonResult(BaseResult.Fail(msg: "验证码不能为空"));
155	            }
156	            //如果不能跳过或者验证不成功
157	            //如果不能跳过或者验证不成功
158	            var chkRet = isCanJumpVerify ? ErrCodeEnum.Success : CaptchaService.Instance.Verify(model.Code, model.Phone, false);
159	            if (chkRet != ErrCodeEnum.Success)
160	            {
