162	            }
163	
164	            var loginChkRet = UserService.Instance.LoginCheck(model.Phone, model.OrgCID);
165	
166	            if (loginChkRet.Item1 != ErrCodeEnum.Success)
167	            {
168	                return JsonResult(BaseResult.CrtEx(loginChkRet.Item1));
169	            }
170	
171	            var userInfo = loginChkRet.Item2;
172	
173	            if (userInfo == null)
174	            {
175	                return JsonResult(BaseResult.Fail());
176	            }
177	
178	
179	            //var userJson = OrgService.Instance.GetOrgUserInfoByPhone(model.Phone);
180	            //if (!userJson.Item1)
181	            //{
182	            //    return JsonResult(BaseResult.CrtEx(ErrCodeEnum.Err, userJson.Item2));
183	            //}
184	
185	            //var userToken = _portalApi.SetSetUserToken(Constansts.PORTAL_CODE_MDIS, model.Phone, model.OrgCID, CookieJson?.UnionId, DigitalSealConfigs.LOGIN_DURATION, userJson.Item2);
186	
