188	
189	            if (string.IsNullOrWhiteSpace(userToken))
190	            {
191	                return JsonResult(BaseResult.CrtEx(ErrCodeEnum.Login_Check_200404));
192	            }
193	
194	            var resUnionId = string.Empty;
195	            // 创建微信用户UnionId绑定关系
196	            if (CookieJson != null)
197	            {
198	                resUnionId = CookieJson?.UnionId;
199	                UserWeChatBindService.Instance.CreateBind(model.Phone,
200	                    Config.SenparcWeixinSetting.WeixinAppId,
201	                    CookieJson?.OpenId,
202	                    CookieJson?.UnionId,
203	                    HttpContextUtility.GetClientIp(),
204	                    HttpContextUtility.GetClientBrowserInfo(),
205	                    userToken);
206	            }
207	            //如果不是微信登录通过手机号查询下UnionId
208	            else
209	            {
210	                var userWeChatBind = UserWeChatBindService.Instance.GetEntityByPhone(model.Phone);
211	                if (userWeChatBind != null)
212	                {
213	                    resUnionId = userWeChatBind.UnionId ?? string.Empty;
214	                }
215	            }
216	
