using System;
using System.Collections.Generic;
using TsingTao.DigitalSeal.Models;

namespace TsingTao.DigitalSeal.Utils
{
    /// <summary>
    /// 敏感信息脱敏工具
    /// </summary>
    public static class MaskUtil
    {
        /// <summary>
        /// 姓名脱敏：保留首字与末字，中间用 * 替代
        /// 1 字不处理；2 字保留首字；3+ 字保留首尾
        /// 例：张三 -> 张*；张三丰 -> 张*丰；慕容云海 -> 慕**海
        /// </summary>
        /// <param name="name">姓名</param>
        /// <returns>脱敏后的姓名</returns>
        public static string MaskName(string name)
        {
            if (string.IsNullOrEmpty(name) || name.Length == 1) return name;
            if (name.Length == 2) return name.Substring(0, 1) + "*";
            var middle = new string('*', name.Length - 2);
            return name.Substring(0, 1) + middle + name.Substring(name.Length - 1, 1);
        }

        /// <summary>
        /// 手机号脱敏：保留前 3 位与后 4 位，中间用 **** 替代
        /// 例：13800138000 -> 138****8000
        /// </summary>
        /// <param name="phone">手机号</param>
        /// <returns>脱敏后的手机号</returns>
        public static string MaskPhone(string phone)
        {
            if (string.IsNullOrEmpty(phone) || phone.Length < 7) return phone;
            return phone.Substring(0, 3) + "****" + phone.Substring(phone.Length - 4);
        }

        /// <summary>
        /// 身份证号脱敏：保留前 4 位与后 4 位（15 位身份证保留末 3 位），中间用 * 替代
        /// 例：110101199001011234 -> 1101**********1234
        ///     110101900101123       -> 1101********123
        /// </summary>
        /// <param name="certNo">身份证号</param>
        /// <returns>脱敏后的身份证号</returns>
        public static string MaskCertNo(string certNo)
        {
            if (string.IsNullOrEmpty(certNo) || certNo.Length <= 8) return certNo;

            // 18 位身份证保留末 4 位，15 位保留末 3 位，其他证件保留末 2 位
            int tailKeep;
            if (certNo.Length >= 18) tailKeep = 4;
            else if (certNo.Length >= 15) tailKeep = 3;
            else tailKeep = 2;

            var middleLength = certNo.Length - 4 - tailKeep;
            if (middleLength <= 0) return certNo;
            var middle = new string('*', middleLength);
            return certNo.Substring(0, 4) + middle + certNo.Substring(certNo.Length - tailKeep);
        }

        /// <summary>
        /// 对 UserInfo 中的姓名/手机号/身份证号进行脱敏（原地修改）
        /// </summary>
        /// <param name="userInfo">用户信息</param>
        public static void Mask(UserInfo userInfo)
        {
            if (userInfo == null) return;
            userInfo.Name = MaskName(userInfo.Name);
            userInfo.Phone = MaskPhone(userInfo.Phone);
            userInfo.CertNo = MaskCertNo(userInfo.CertNo);
        }

        /// <summary>
        /// 复制 UserInfo 并对姓名/手机号/身份证号进行脱敏（不影响原对象）
        /// </summary>
        /// <param name="userInfo">用户信息</param>
        /// <returns>脱敏后的新对象</returns>
        public static UserInfo ToMasked(UserInfo userInfo)
        {
            if (userInfo == null) return null;
            var clone = (UserInfo)userInfo.MemberwiseClone();
            Mask(clone);
            return clone;
        }

        /// <summary>
        /// 对 UserFullInfo 列表中每一项的姓名/手机号/身份证号进行脱敏（原地修改）
        /// </summary>
        /// <param name="list">用户全量信息列表</param>
        public static void MaskList(IList<UserFullInfo> list)
        {
            if (list == null) return;
            foreach (var item in list)
            {
                Mask(item);
            }
        }

        /// <summary>
        /// 对组织信息中的法人姓名/法人证件号/法人手机号进行脱敏（原地修改）
        /// </summary>
        /// <param name="orgInfo">组织信息</param>
        public static void Mask(OrgInfo orgInfo)
        {
            if (orgInfo == null) return;
            orgInfo.LegalPersonName = MaskName(orgInfo.LegalPersonName);
            orgInfo.LegalPersonPhone = MaskPhone(orgInfo.LegalPersonPhone);
            orgInfo.LegalPersonCertNo = MaskCertNo(orgInfo.LegalPersonCertNo);
        }
    }
}

