1	using System;
2	using System.Collections.Generic;
3	using TsingTao.DigitalSeal.Models;
4	
5	namespace TsingTao.DigitalSeal.Utils
6	{
7	    /// <summary>
8	    /// 敏感信息脱敏工具
9	    /// </summary>
10	    public static class MaskUtil
11	    {
12	        /// <summary>
13	        /// 姓名脱敏：保留首字与末字，中间用 * 替代
14	        /// 1 字不处理；2 字保留首字；3+ 字保留首尾
15	        /// 例：张三 -> 张*；张三丰 -> 张*丰；慕容云海 -> 慕**海
16	        /// </summary>
17	        /// <param name="name">姓名</param>
18	        /// <returns>脱敏后的姓名</returns>
19	        public static string MaskName(string name)
20	        {
21	            if (string.IsNullOrEmpty(name) || name.Length == 1) return name;
22	            if (name.Length == 2) return name.Substring(0, 1) + "*";
23	            var middle = new string('*', name.Length - 2);
24	            return name.Substring(0, 1) + middle + name.Substring(name.Length - 1, 1);
25	        }
26	
27	        /// <summary>
28	        /// 手机号脱敏：保留前 3 位与后 4 位，中间用 **** 替代
29	        /// 例：13800138000 -> 138****8000
30	        /// </summary>
31	        /// <param name="phone">手机号</param>
32	        /// <returns>脱敏后的手机号</returns>
33	        public static string MaskPhone(string phone)
34	        {
35	            if (string.IsNullOrEmpty(phone) || phone.Length < 7) return phone;
36	            return phone.Substring(0, 3) + "****" + phone.Substring(phone.Length - 4);
37	        }
38	
39	        /// <summary>
40	        /// 身份证号脱敏：保留前 4 位与后 4 位（15 位身份证保留末 3 位），中间用 * 替代
41	        /// 例：110101199001011234 -> 1101**********1234
42	        ///     110101900101123       -> 1101********123
43	        /// </summary>
44	        /// <param name="certNo">身份证号</param>
45	        /// <returns>脱敏后的身份证号</returns>
46	        public static string MaskCertNo(string certNo)
47	        {
48	            if (string.IsNullOrEmpty(certNo) || certNo.Length <= 8) return certNo;
49	
50	            // 18 位身份证保留末 4 位，15 位保留末 3 位，其他证件保留末 2 位
51	            int tailKeep;
52	            if (certNo.Length >= 18) tailKeep = 4;
53	            else if (certNo.Length >= 15) tailKeep = 3;
54	            else tailKeep = 2;
55	
56	            var middleLength = certNo.Length - 4 - tailKeep;
57	            if (middleLength <= 0) return certNo;
58	            var middle = new string('*', middleLength);
59	            return certNo.Substring(0, 4) + middle + certNo.Substring(certNo.Length - tailKeep);
60	        }
61	
62	        /// <summary>
63	        /// 对 UserInfo 中的姓名/手机号/身份证号进行脱敏（原地修改）
64	        /// </summary>
65	        /// <param name="userInfo">用户信息</param>
66	        public static void Mask(UserInfo userInfo)
67	        {
68	            if (userInfo == null) return;
69	            userInfo.Name = MaskName(userInfo.Name);
70	            userInfo.Phone = MaskPhone(userInfo.Phone);
71	            userInfo.CertNo = MaskCertNo(userInfo.CertNo);
72	        }
73	
74	        /// <summary>
75	        /// 复制 UserInfo 并对姓名/手机号/身份证号进行脱敏（不影响原对象）
76	        /// </summary>
77	        /// <param name="userInfo">用户信息</param>
78	        /// <returns>脱敏后的新对象</returns>
79	        public static UserInfo ToMasked(UserInfo userInfo)
80	        {
81	            if (userInfo == null) return null;
82	            var clone = (UserInfo)userInfo.MemberwiseClone();
83	            Mask(clone);
84	            return clone;
85	        }
86	
87	        /// <summary>
88	        /// 对 UserFullInfo 列表中每一项的姓名/手机号/身份证号进行脱敏（原地修改）
89	        /// </summary>
90	        /// <param name="list">用户全量信息列表</param>
91	        public static void MaskList(IList<UserFullInfo> list)
92	        {
93	            if (list == null) return;
94	            foreach (var item in list)
95	            {
96	                Mask(item);
97	            }
98	        }
99	
100	        /// <summary>
101	        /// 对组织信息中的法人姓名/法人证件号/法人手机号进行脱敏（原地修改）
102	        /// </summary>
103	        /// <param name="orgInfo">组织信息</param>
104	        public static void Mask(OrgInfo orgInfo)
105	        {
106	            if (orgInfo == null) return;
107	            orgInfo.LegalPersonName = MaskName(orgInfo.LegalPersonName);
108	            orgInfo.LegalPersonPhone = MaskPhone(orgInfo.LegalPersonPhone);
109	            orgInfo.LegalPersonCertNo = MaskCertNo(orgInfo.LegalPersonCertNo);
110	        }
111	    }
